const C=AquaCore,$=s=>document.querySelector(s),esc=C.escape;
let data,cursor=0,active='overview',metric='DO',chartDays=2,playing=false,timer=null,eventFilter='all',dayFilter='all',labMetric='DO',auditFilter='all';
let journal=[];try{journal=JSON.parse(localStorage.getItem('aquatwin-journal-v1')||'[]');if(!Array.isArray(journal))journal=[]}catch{}
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',twin:'<path d="M12 3 3 8v9l9 5 9-5V8zM3 8l9 5 9-5M12 13v9"/>',quality:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM8 12l3 3 5-6"/>',events:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',insights:'<path d="M3 20V4M3 20h18M7 15l4-5 4 3 6-8"/>',lab:'<path d="M9 3h6M10 3v7L4 20h16l-6-10V3M7 15h10"/>',journal:'<path d="M6 3h12v18H6zM9 7h6M9 11h6M9 15h4"/>',data:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>'};
const navItems=[['overview','Overview'],['twin','Digital Twin'],['quality','Data quality'],['events','Events to review'],['insights','Environmental insights'],['lab','Research lab'],['journal','Operations log'],['data','Data & settings']];
const svgIcon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${icons[k]||icons.overview}</svg>`;
const f=(v,n=2)=>v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:n});
const date=s=>s?`${s.slice(8,10)}/${s.slice(5,7)}/${s.slice(0,4)} · ${s.slice(11,19)}`:'—';
const pill=flag=>`<span class="pill ${C.flagClasses[flag]}">● ${C.flagNames[flag]}</span>`;
const row=()=>data.rows[cursor];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(title,body){$('#modalBody').innerHTML=`<h2>${title}</h2>${body}`;$('#modal').showModal()}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-buttons">${actions}</div></div>`}
function notice(){return `<div class="notice"><span>ⓘ</span><div><strong>Historical observations · ${date(row().ts)} (UTC+7)</strong> — Provisional QC flags assess data, not fish health. Depth, cage location and calibration are unconfirmed.</div></div>`}
function frame(title,body,sub='',right=''){return `<section class="card"><div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${body}</section>`}
function metricSelector(id='metric'){return `<select id="${id}" aria-label="Select parameter">${C.keys.map(k=>`<option value="${k}" ${metric===k?'selected':''}>${data.params[k].label}</option>`).join('')}</select>`}
function subset(days=chartDays){const end=C.stamp(row().ts),start=end-days*86400000;return data.rows.slice(0,cursor+1).filter(r=>C.stamp(r.ts)>=start)}
function chart(rows,key,{height=230,values=null,color='#168572'}={}){if(rows.length<2)return '<div class="empty">Select more records on the replay timeline to view the chart.</div>';const W=780,H=height,left=48,right=18,top=20,bottom=32;const nums=values||rows.map(r=>r.values[key]);const valid=nums.filter(v=>v!=null);if(!valid.length)return '<div class="empty">No measurements in this interval.</div>';let low=Math.min(...valid),high=Math.max(...valid),pad=(high-low)*.18||.5;low-=pad;high+=pad;const times=rows.map(r=>C.stamp(r.ts)),start=times[0],end=times.at(-1);const x=i=>left+(times[i]-start)/(end-start||1)*(W-left-right),y=v=>top+(high-v)/(high-low)*(H-top-bottom);let paths=[],path='';for(let i=0;i<rows.length;i++){if(nums[i]==null||(i&&times[i]-times[i-1]>1800000)){if(path)paths.push(path);path='';if(nums[i]==null)continue}path+=(path?'L':'M')+x(i).toFixed(2)+','+y(nums[i]).toFixed(2)}if(path)paths.push(path);let grid='';for(let i=0;i<5;i++){const v=low+(high-low)*i/4,yy=y(v);grid+=`<line class="grid" x1="${left}" x2="${W-right}" y1="${yy}" y2="${yy}"/><text x="${left-9}" y="${yy+3}" text-anchor="end">${f(v,1)}</text>`}for(let i=0;i<5;i++){const idx=Math.round((rows.length-1)*i/4),ts=rows[idx].ts;grid+=`<text x="${x(idx)}" y="${H-8}" text-anchor="middle">${ts.slice(11,16)}${chartDays>1?' · '+ts.slice(8,10)+'/'+ts.slice(5,7):''}</text>`}const points=rows.map((r,i)=>{if(nums[i]==null)return '';const idx=data.rows.indexOf(r),flag=C.qcAt(data.rows,idx,key,cursor).flag;return flag===3||flag===4?`<circle cx="${x(i)}" cy="${y(nums[i])}" r="3" fill="${flag===4?'#c75e51':'#d7a442'}"><title>${esc(date(r.ts))}: ${f(nums[i])} · ${C.flagNames[flag]}</title></circle>`:''}).join('');return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Trends: ${esc(data.params[key].label)}">${grid}${paths.map(p=>`<path d="${p}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round"/>`).join('')}${points}</svg></div>`}
function timeline(){return `<div class="timeline"><button id="playBtn" class="button small secondary">${playing?'Ⅱ Pause':'▷ Replay'}</button><input type="range" id="cursor" min="0" max="${data.rows.length-1}" value="${cursor}" aria-label="Replay time"><span class="timestamp">${date(row().ts)}</span><button id="latestBtn" class="text-link">Latest record →</button></div>`}
function metricCards(){return `<div class="metrics">${C.keys.map((k,i)=>{const q=C.qcAt(data.rows,cursor,k,cursor);const val=row().values[k];return `<article class="metric"><div class="metric-top"><span>${data.params[k].label}</span><span class="metric-icon">${['♧','ϟ','◉','◌','≋'][i]}</span></div><div class="metric-value">${f(val)}<small>${data.params[k].unit}</small></div><div class="metric-bottom">${pill(q.flag)}<span>Observed</span></div></article>`}).join('')}</div>`}
function eventList(list,limit=4){return list.length?`<div class="event-list">${list.slice(0,limit).map(e=>`<div class="event-item"><span class="event-icon">${e.flag===9?'⌁':'!'}</span><div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p><button class="text-link event-open" data-id="${e.id}">View & review →</button></div><span class="event-time">${data.rows[e.i].ts.slice(8,10)}/${data.rows[e.i].ts.slice(5,7)}<br>${data.rows[e.i].ts.slice(11,16)}</span></div>`).join('')}</div>`:'<div class="empty">No events in this interval.</div>'}
function qualitySummary(){const n=C.summary(data,cursor),total=Object.values(n).reduce((a,b)=>a+b,0);return `<div class="stats-row"><div class="stat"><span class="label">QC-PASSED OBSERVATIONS</span><strong>${f(n[1]/total*100,1)}<small style="font-size:13px">%</small></strong></div><div class="stat"><span class="label">REPLAYED RECORDS</span><strong>${f(cursor+1,0)}</strong></div></div><div class="progress">${[1,3,4,9].map(k=>`<span style="width:${n[k]/total*100}%;background:${{1:'#71ab8e',3:'#e2b966',4:'#cc7970',9:'#b8c6cf'}[k]}"></span>`).join('')}</div>${[1,3,4,9].map(k=>`<div class="quality-item"><span>${pill(k)}</span><span class="count">${f(n[k],0)} measurements</span></div>`).join('')}<p class="section-note">5 measurements per record. Spike QC at the replay cursor awaits the next sample.</p>`}
function overview(){return heading('AQUATWIN / MONITORING STATION','Understand the water. Inspect proactively.','Monitor water conditions, review data and record actions at Marine Farm 2.',`<button class="button secondary" data-go="data">☷ Data sources</button><button class="button" data-go="journal">＋ Record an inspection</button>`)+notice()+metricCards()+`<div class="two-col"><div>${frame('Water-quality trends',chart(subset(),metric)+`<div class="chart-caption"><span><i></i>Original readings</span><span>● QC points to review</span><span>Gaps are not interpolated</span></div>`+timeline(),'Measurements at the selected replay time',`<div class="chart-toolbar">${metricSelector()}<div class="segmented"><button data-days="1" class="${chartDays===1?'active':''}">24 hours</button><button data-days="2" class="${chartDays===2?'active':''}">48 hours</button><button data-days="14" class="${chartDays===14?'active':''}">All</button></div></div>`)}</div><div>${frame('Digital monitoring station',`<div class="station-scene"><span class="scene-tag">ILLUSTRATIVE DIAGRAM · NOT THE ACTUAL LOCATION</span><svg viewBox="0 0 180 100" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M15 48h150M25 48v33l65 13 65-13V48M25 48l65 16 65-16M90 64v30M25 64l65 16 65-16M50 54v32M130 54v32M15 48l30-16h90l30 16M90 14v38M81 15h18M86 9h8"/><circle cx="90" cy="48" r="6" fill="#8bb9a9"/><path d="M3 69q10-5 20 0M157 69q10-5 20 0"/></svg></div><div class="station-title"><strong>Marine Farm 2</strong><span class="pill pass">● Historical data available</span></div><div class="meta-list"><div><span>Twin identifier</span><strong>aquatwin:nuoibien-2</strong></div><div><span>Source device</span><strong>nuoibienvien3</strong></div><div><span>Depth / calibration</span><strong>Unconfirmed</strong></div><div><span>Ditto integration</span><strong>Contract available</strong></div></div><div class="divider"></div><button class="text-link" data-go="twin">Explore the twin model →</button>`)}</div></div><div class="two-col"><div>${frame('Events to review',eventList(C.events(data,cursor),3),'Data-quality signals; causes are not established',`<button class="text-link" data-go="events">View all →</button>`)}</div><div>${frame('Data health',qualitySummary(),'Provisional QC · '+data.meta.qcVersion)}</div></div>`}
function twin(){const t=C.currentTwin(data,cursor);return heading('ENTITY MODEL','One real source. Traceable states.','Observations, relationships and last_good are managed per parameter.',`<button class="button" id="downloadTwin">↓ Export Thing JSON</button>`)+notice()+frame('Entity relationships',`<div class="twin-graph"><div class="node">Marine Farm 2 station<small>FarmSite · site: NuoiBien_2</small></div><span class="connector">→ contains →</span><div class="node primary">WQI monitoring station<small>aquatwin:nuoibien-2</small></div><span class="connector">← observes ←</span><div class="node">nuoibienvien3<small>5 measurement streams · observed</small></div></div><p class="annotation">Cage/pond, fish stock, probe position and depth are unconfirmed. The prototype does not invent stock or equipment relationships.</p>`)+frame('Feature states',`<div class="table-wrap"><table><thead><tr><th>Feature</th><th>Observation at cursor</th><th>Aggregate QC</th><th>Last good</th><th>Last-good time</th></tr></thead><tbody>${C.keys.map(k=>{const p=t.features[k].properties;return `<tr><td>${data.params[k].label}</td><td>${f(p.observed.value)} ${data.params[k].unit}</td><td>${pill(p.observed.qualityFlag)}</td><td>${f(p.last_good?.value)}</td><td>${date(p.last_good?.ts)}</td></tr>`}).join('')}</tbody></table></div><p class="section-note">Observed values remain unchanged even when QC fails. last_good does not replace the current reading. Spike QC is finalized when the next sample is available.</p>`)+frame('Eclipse Ditto-compatible contract',`<pre class="code">${esc(JSON.stringify(t,null,2))}</pre><p class="section-note">This browser projection is not connected to a Ditto server. A snapshot adapter is available once an endpoint and permissions are configured.</p>`)}
function quality(){return heading('DATA QUALITY / QC','Check data before making decisions.','Six checks from prototype.md. Provisional QC thresholds are not biological limits.')+notice()+`<div class="two-col"><div>${frame('Quality-flag distribution',qualitySummary())}${frame('Checks at replay time',`<div class="table-wrap"><table><thead><tr><th>Parameter</th><th>Missing</th><th>Gross range</th><th>Site range</th><th>Spike</th><th>ROC</th><th>Flat line</th></tr></thead><tbody>${C.keys.map(k=>{const q=C.qcAt(data.rows,cursor,k,cursor);return `<tr><td>${data.params[k].label}</td>${Object.values(q.tests).map(v=>`<td>${pill(v)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`+timeline(),'Spike QC requires the next sample and remains pending at the cursor.')}</div><div>${frame('Data interruptions',eventList(C.events(data,cursor).filter(e=>e.kind==='gap'||e.kind==='device'),8),'Missing data is not evidence of safety')}${frame('Units clarified',`<p class="small-copy"><strong>salinity → conductivity</strong><br>The source key represents conductivity in mS/cm, not salinity in PSU, as confirmed in prototype.md.</p><p class="small-copy">Legacy percent saturation, oxygen solubility and oxygen deficit were excluded because they used an incorrect salinity assumption. They are not used in alerts or forecasts.</p><p class="small-copy">PSS-78 is not computed in this version; a suitable library and confirmed device temperature compensation are required before operational use.</p>`)}</div></div>`}
function eventsPage(){let list=C.events(data,cursor);if(eventFilter!=='all')list=list.filter(e=>eventFilter==='device'?['device','gap'].includes(e.kind):!['device','gap'].includes(e.kind));return heading('EVENTS / REVIEW','From data signals to field inspections.','Each event includes evidence; conclusions are recorded by the responsible operator.',`<button class="button secondary" id="exportEvents">↓ Export events</button>`)+`<div class="tabs"><button data-filter="all" class="${eventFilter==='all'?'active':''}">All</button><button data-filter="water" class="${eventFilter==='water'?'active':''}">Parameter changes</button><button data-filter="device" class="${eventFilter==='device'?'active':''}">Devices & interruptions</button></div>`+frame(`${list.length} QC signals in the replayed interval`,eventList(list,70),'Showing up to 70 recent signals. They are not grouped into biological incidents.')}
function insights(){const arr=data.rows.slice(0,cursor+1);const daily={};for(const r of arr){const dateKey=r.ts.slice(0,10);if(!daily[dateKey])daily[dateKey]=[];if(r.values[metric]!=null&&C.qcAt(data.rows,data.rows.indexOf(r),metric,cursor).flag===1)daily[dateKey].push(r.values[metric])}const days=Object.entries(daily).map(([day,vs])=>({day,n:vs.length,mean:vs.length?vs.reduce((a,b)=>a+b,0)/vs.length:null,min:vs.length?Math.min(...vs):null,max:vs.length?Math.max(...vs):null}));return heading('ENVIRONMENT / FARM CHALLENGES','Turn data into questions worth checking.','Analyze available water data; drivers, health and waste require additional evidence.')+`<div class="issue-grid">${[['01 / WATER QUALITY','Oxygen & environmental changes','Track DO, temperature, pH and conductivity. Species-specific safety thresholds are not configured.','quality','View data'],['02 / WASTE','Turbidity & events to review','A spike does not establish uneaten feed. Sampling, feeding logs and context are required.','events','View events'],['03 / HEALTH','Fish observations & feeding response','Record a health inspection. Five water parameters do not provide a disease diagnosis.','journal','Record'],['04 / EXTERNAL CONDITIONS','Weather & water exchange','Rain, wind and current data are unavailable. Causes of water changes are not inferred.','journal','Add a log entry'],['05 / EFFICIENCY','Feeding & equipment','Feed quantities, biomass and power data are unavailable. Start a logbook to support future models.','journal','Record operations'],['06 / RELIABILITY','Missing data & probes','Separate measurement faults from environmental conditions. Review suspect points.','quality','Review QC']].map(([num,title,desc,to,label])=>`<article class="issue-card"><div class="issue-number">${num}</div><h3>${title}</h3><p>${desc}</p><button class="text-link" data-go="${to}">${label} →</button></article>`).join('')}</div>`+frame('Daily trends and statistics',chart(subset(14),metric)+`<div class="table-wrap"><table><thead><tr><th>Date</th><th>QC-passed readings</th><th>Mean</th><th>Minimum</th><th>Maximum</th></tr></thead><tbody>${days.map(v=>`<tr><td>${v.day}</td><td>${v.n}</td><td>${f(v.mean)}</td><td>${f(v.min)}</td><td>${f(v.max)}</td></tr>`).join('')}</tbody></table></div>`,'Only QC-passed samples are summarized; their mean is not a whole-water-volume average.',metricSelector())}
function lab(){const b=C.backtest(data,labMetric);return heading('RESEARCH / SANDBOX','Experiment first. Verify first.','Experimental results do not authorize operational forecasts or equipment control.')+`<div class="notice warn"><span>◇</span><div><strong>Isolated research sandbox.</strong> Backtesting uses the full historical snapshot, not live data or an independently validated forecast.</div></div><div class="two-col"><div>${frame('Forecast benchmark: persistence',`<div class="form-grid"><div class="field"><label>Test parameter</label><select id="labMetric">${C.keys.map(k=>`<option value="${k}" ${k===labMetric?'selected':''}>${data.params[k].label}</option>`).join('')}</select></div><div class="field"><label>Design</label><input readonly value="Last 30% evaluation · next-sample forecast"></div></div><div class="divider"></div>${b.count?`<div class="stats-row"><div class="stat"><span class="label">MAE</span><strong>${f(b.mae,3)}</strong></div><div class="stat"><span class="label">RMSE</span><strong>${f(b.rmse,3)}</strong></div><div class="stat"><span class="label">VALID PAIRS</span><strong>${b.count}</strong></div></div><p class="small-copy">Evaluation: ${date(b.start)} to ${date(b.end)}.<br>Forecast y(t+1) = y(t). Excludes errors, gaps over 30 minutes and failed input QC. Future-dependent spike checks are not used to select inputs.</p><p class="annotation">This baseline describes historical errors, not an improvement over a benchmark. The horizon is the next irregular sample; no validated uncertainty interval is provided.</p>`:'<div class="empty">Not enough valid pairs.</div>'}`)}${frame('Data-fault simulation',`<p class="small-copy">Inject a fault at replay time to inspect system behavior. The source snapshot is unchanged.</p><label class="checkbox"><input type="radio" name="fault" value="dropout" checked> Data-stream outage for 45 minutes</label><label class="checkbox"><input type="radio" name="fault" value="duplicate"> Duplicate the current event</label><label class="checkbox"><input type="radio" name="fault" value="late"> Older record arrives after the current state</label><button class="button" id="runScenario">▷ Run scenario</button><div id="scenarioResult"></div>`)}</div><div>${frame('Model-release gates',`<div class="step"><span class="step-num">1</span><div><strong>Observations & QC</strong><br><span class="muted">Real data; provisional quality thresholds.</span></div></div><div class="step"><span class="step-num">2</span><div><strong>Time-based backtesting</strong><br><span class="muted">Reproducible baseline; not independently validated.</span></div></div><div class="step"><span class="step-num">3</span><div><strong>Assess the validity domain</strong><br><span class="muted">Requires held-out seasons/sites, uncertainty assessment and review.</span></div></div><div class="step"><span class="step-num">4</span><div><strong>Operational release</strong><br><span class="muted">Not released. Forecasts do not trigger actions.</span></div></div>`)}${frame('Physical-intervention simulation',`<span class="pill unknown">Awaiting data</span><p class="small-copy">Aeration and feed reductions are not simulated. Pond/cage configuration, volume, biomass, currents, equipment states and intervention data are required.</p><p class="small-copy">A hypothetical numeric change is not a verified effect on fish.</p>`)}</div></div>`}
function journalPage(){const entries=journal.filter(e=>auditFilter==='all'||e.type===auditFilter);return heading('FARMOS / LOGBOOK','Record actions. Preserve evidence.','Logs are stored in this browser. Export a file to share; devices do not synchronize automatically.',`<button class="button secondary" id="exportJournal">↓ Export logbook</button>`)+`<div class="two-col"><div>${frame('Field record',`<form id="journalForm"><div class="form-grid"><div class="field"><label for="entryType">Record type</label><select id="entryType" name="type"><option value="inspection">Environmental inspection</option><option value="health">Fish-health observation</option><option value="feeding">Feeding</option><option value="equipment">Equipment / maintenance</option><option value="weather">Weather / currents</option></select></div><div class="field"><label for="entryTime">Time (source timezone UTC+7)</label><input id="entryTime" name="time" type="datetime-local" required value="${row().ts.slice(0,16)}"></div><div class="field"><label for="entryOwner">Operator</label><input id="entryOwner" name="owner" required maxlength="100" placeholder="Inspector name"></div><div class="field"><label for="entryTarget">Target / location</label><input id="entryTarget" name="target" required maxlength="120" value="Marine Farm 2 station"></div><div class="field"><label for="entryStatus">Review outcome</label><select id="entryStatus" name="status"><option>Cause undetermined</option><option>Suspected equipment issue</option><option>Cross-check completed</option><option>Specialist review needed</option></select></div><div class="field"><label for="entryQuantity">Quantity / unit (optional)</label><input id="entryQuantity" name="quantity" maxlength="80" placeholder="Example: 12 kg of feed"></div><div class="field wide"><label for="entryNote">Observations, actions and evidence</label><textarea id="entryNote" name="note" required maxlength="3000" placeholder="Record facts; distinguish observations from interpretations…"></textarea></div></div><div class="form-actions"><button type="submit" class="button">＋ Save record</button><button type="reset" class="button secondary">Reset</button></div></form>`)}</div><div>${frame('From data to decisions',`<p class="small-copy">1. Identify a data event.<br>2. Cross-check measurements / inspect the farm.<br>3. The responsible operator records actions.<br>4. Monitor outcomes and water trends.</p><div class="divider"></div><p class="small-copy">No farm-approved biological thresholds, disease diagnosis, feeding commands or aeration commands are available.</p><p class="annotation">New entries are user observations, separate from the source CSV. Local storage does not replace a managed logbook system.</p>`)}</div></div>`+frame(`Saved records (${entries.length})`,entries.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Type</th><th>Operator</th><th>Outcome / notes</th></tr></thead><tbody>${entries.slice().reverse().map(e=>`<tr><td>${date(e.time)}</td><td>${esc(typeLabel(e.type))}</td><td>${esc(e.owner)}</td><td style="white-space:normal;min-width:250px">${esc(e.note)}<br><span class="muted">${esc(e.status)} ${e.quantity?'· '+esc(e.quantity):''}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No records yet. Add your first observation to connect actions with data.</div>')}
function typeLabel(t){return {inspection:'Water inspection',health:'Fish health',feeding:'Feeding',equipment:'Equipment',weather:'Weather',event:'QC review'}[t]||t}
function dataPage(){const displayed=data.rows.slice(0,cursor+1).filter(r=>dayFilter==='all'||r.ts.startsWith(dayFilter));return heading('DATA SOURCES / SETTINGS','Clear data. Traceable results.','1,333 records · 30 Oct–12 Nov 2026 · NuoiBien_2 · Source CSV unchanged.',`<button class="button secondary" id="downloadQC">↓ Export QC settings</button><button class="button" id="exportNormalized">↓ Export normalized CSV</button>`)+`<div class="notice warn"><span>ⓘ</span><div><strong>Data interpretation correction:</strong> source key <code>salinity</code> represents conductivity in mS/cm. Legacy derived oxygen indices are excluded. Conductivity is not Practical Salinity.</div></div>`+`<div class="two-col"><div>${frame('Source profile',`<div class="meta-list"><div><span>Equipment</span><strong>${esc(data.meta.device)}</strong></div><div><span>Timezone</span><strong>UTC+07:00 · theo prototype.md</strong></div><div><span>Data</span><strong>${data.rows.length} records / ${data.rows.length*5} measurements</strong></div><div><span>Depth / cage / calibration</span><strong>Unconfirmed</strong></div></div><div class="divider"></div><p class="small-copy">Source: ${esc(data.meta.source)}<br>SHA-256: <code style="word-break:break-all">${esc(data.meta.sha256)}</code></p><p class="small-copy">Units °C, mg/L and NTU are documented in GREEN-X via prototype.md. Conductivity mS/cm is confirmed in project notes. Provisional QC limits are not biological limits.</p>`)}${frame('Provisional QC ranges',`<div class="table-wrap"><table><thead><tr><th>Parameter</th><th>Gross range</th><th>Site plausible</th><th>ROC / hours</th></tr></thead><tbody>${C.keys.map(k=>`<tr><td>${data.params[k].label}</td><td>${data.params[k].gross.join(' – ')}</td><td>${data.params[k].plausible.join(' – ')}</td><td>${data.params[k].roc}</td></tr>`).join('')}</tbody></table></div><p class="section-note">Per prototype.md: two-neighbor spike check, flatline suspect at 4h / fail at 12h; gaps over 30 minutes generate events. This app implementation has not been verified bit-for-bit against the separate pipeline.</p>`)}</div><div>${frame('Capability status',`<div class="quality-item"><span>Observations & replay</span><span class="pill pass">Available</span></div><div class="quality-item"><span>QC & events</span><span class="pill suspect">Provisional</span></div><div class="quality-item"><span>Logbook</span><span class="pill pass">Browser storage</span></div><div class="quality-item"><span>Eclipse Ditto</span><span class="pill unknown">Not connected</span></div><div class="quality-item"><span>Operational forecasting</span><span class="pill unknown">Not released</span></div><div class="quality-item"><span>Camera / acoustics</span><span class="pill unknown">Not loaded</span></div><div class="quality-item"><span>Device actuation</span><span class="pill unknown">Not implemented</span></div>`)}</div></div>`+frame(`Normalized records · ${displayed.length} samples in scope`, `<div class="table-wrap"><table><thead><tr><th>Time UTC+7</th>${C.keys.map(k=>`<th>${data.params[k].label} (${data.params[k].unit||'1'})</th>`).join('')}<th>Source error</th></tr></thead><tbody>${displayed.slice(-100).reverse().map(r=>`<tr><td>${date(r.ts)}</td>${C.keys.map(k=>`<td>${f(r.values[k])}</td>`).join('')}<td>${r.error?'Serial-port error':'—'}</td></tr>`).join('')}</tbody></table></div><p class="section-note">Showing the 100 latest filtered records. Export the CSV to view all data.</p>`,'Original values are preserved; only the conductivity field name is normalized.',`<select id="dayFilter" aria-label="Filter dates"><option value="all">All dates</option>${[...new Set(data.rows.map(r=>r.ts.slice(0,10)))].map(day=>`<option ${day===dayFilter?'selected':''}>${day}</option>`).join('')}</select>`)}
function render(){const found=navItems.find(n=>n[0]===active);$('#breadcrumb').textContent=found?.[1]||'Overview';$('#nav').innerHTML=navItems.map(([id,label])=>`<a href="#${id}" class="${active===id?'active':''}">${svgIcon(id)}<span>${label}</span>${id==='events'?'<span class="nav-num">QC</span>':''}</a>`).join('');$('#page').innerHTML=({overview,twin,quality,events:eventsPage,insights,lab,journal:journalPage,data:dataPage}[active]||overview)();bind()}
function saveJournal(entry){const next=[...journal,entry];try{localStorage.setItem('aquatwin-journal-v1',JSON.stringify(next));journal=next;return true}catch{toast('Unable to save. Check browser storage and try again.');return false}}
function openEvent(id){const e=C.events(data,cursor).find(e=>e.id===id);if(!e)return;const r=data.rows[e.i];modal(esc(e.title),`<p>${esc(e.detail)}</p><p><strong>Time:</strong> ${date(r.ts)} (UTC+7)<br><strong>Event ID:</strong> ${esc(e.id)}</p><p class="small-copy">This is a QC signal, not a disease diagnosis or pollution finding. Verification requires a field inspection.</p><form id="eventForm"><div class="field"><label>Reviewer</label><input name="owner" required maxlength="100"></div><div class="spacer"></div><div class="field"><label>Notes / evidence</label><textarea name="note" required maxlength="3000"></textarea></div><div class="form-actions"><button class="button" type="submit">Save to logbook</button><button class="button secondary" type="button" id="jumpEvent">View at this time</button></div></form>`);$('#eventForm').onsubmit=ev=>{ev.preventDefault();const form=new FormData(ev.target);if(saveJournal({id:crypto.randomUUID(),type:'event',time:r.ts,owner:form.get('owner'),target:r.site,status:'Review recorded',note:form.get('note'),eventId:id,createdAt:new Date().toISOString()})){$('#modal').close();toast('Review saved in the local logbook.')}};$('#jumpEvent').onclick=()=>{$('#modal').close();cursor=e.i;active='overview';location.hash='overview';render()}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);document.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{chartDays=Number(b.dataset.days);render()});$('#metric')?.addEventListener('change',e=>{metric=e.target.value;render()});$('#cursor')?.addEventListener('input',e=>{cursor=Number(e.target.value);render()});$('#playBtn')?.addEventListener('click',()=>{playing=!playing;if(playing){if(cursor===data.rows.length-1)cursor=0;timer=setInterval(()=>{cursor=Math.min(cursor+1,data.rows.length-1);if(cursor===data.rows.length-1){playing=false;clearInterval(timer)}render()},650)}else clearInterval(timer);render()});$('#latestBtn')?.addEventListener('click',()=>{cursor=data.rows.length-1;render()});$('#downloadTwin')?.addEventListener('click',()=>download('aquatwin-thing.json',JSON.stringify(C.currentTwin(data,cursor),null,2),'application/json'));document.querySelectorAll('.event-open').forEach(b=>b.onclick=()=>openEvent(b.dataset.id));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{eventFilter=b.dataset.filter;render()});$('#exportEvents')?.addEventListener('click',()=>download('aquatwin-qc-events.json',JSON.stringify(C.events(data,cursor),null,2),'application/json'));$('#labMetric')?.addEventListener('change',e=>{labMetric=e.target.value;render()});$('#runScenario')?.addEventListener('click',runScenario);$('#exportJournal')?.addEventListener('click',()=>download('aquatwin-journal.json',JSON.stringify(journal,null,2),'application/json'));$('#journalForm')?.addEventListener('submit',ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(ev.target));if(!values.owner.trim()||!values.note.trim())return toast('Enter an operator and notes.');if(saveJournal({...values,id:crypto.randomUUID(),createdAt:new Date().toISOString(),sourceSnapshot:row().id})){render();toast('Log saved in this browser.')}});$('#dayFilter')?.addEventListener('change',e=>{dayFilter=e.target.value;render()});$('#downloadQC')?.addEventListener('click',()=>download('aquatwin-qc-provisional.json',JSON.stringify({version:data.meta.qcVersion,biologicalAlarm:false,params:data.params},null,2),'application/json'));$('#exportNormalized')?.addEventListener('click',exportData)}
function runScenario(){const kind=document.querySelector('input[name=fault]:checked').value,current=C.currentTwin(data,cursor);let result;if(kind==='dropout'){const future=C.stamp(row().ts)+45*60000,age=(future-C.stamp(row().ts))/60000;result={scenario:'45-minute data outage',stateKind:'simulated',sourceValueUnchanged:true,simulatedDataAgeMinutes:age,stale:age>30,recommendationEligible:false,result:'Data exceeds the 30-minute trial freshness limit and cannot represent the current state. Missing data does not establish fish conditions.'}}else if(kind==='duplicate'){const seen=new Set();let accepted=0;for(const r of [row(),row()])if(!seen.has(r.id)){seen.add(r.id);accepted++}result={scenario:'Duplicate event',stateKind:'simulated',received:2,accepted,duplicates:2-accepted,result:'One logical update; no extra measurement is created.'}}else{const old=data.rows[Math.max(0,cursor-5)],latestTs=row().ts;let projected=latestTs;if(C.stamp(old.ts)>C.stamp(projected))projected=old.ts;result={scenario:'Late-arriving record',stateKind:'simulated',lateTime:old.ts,currentTime:latestTs,projectionTime:projected,historyCorrection:true,result:projected===latestTs?'Append to history without moving the current state backward.':'Updated in event-time order.'}}$('#scenarioResult').innerHTML=`<div class="divider"></div><span class="pill pass">Run completed on a copy</span><pre class="code">${esc(JSON.stringify(result,null,2))}</pre>`}
function exportData(){const headers=['site','device','ts','temperature_degC','conductivity_mS_cm','pH','DO_mg_L','turbidity_NTU','sensor_error'];const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[headers.join(','),...data.rows.map(r=>[r.site,r.device,r.ts,...C.keys.map(k=>r.values[k]),r.error].map(quote).join(','))].join('\r\n');download('aquatwin-normalized-observations.csv','\ufeff'+csv,'text/csv;charset=utf-8')}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});$('#aboutBtn').onclick=()=>modal('Scope & data sources',`<p>AquaTwin is a historical-observation prototype with 1,333 WQI records. The browser runs the twin core; Ditto contracts and an adapter are available but no live server is connected.</p><p>Per prototype.md (14 Nov 2026): salinity means conductivity mS/cm; timestamps are UTC+7; provisional QC limits are not biological thresholds. Incorrect legacy oxygen indices are excluded.</p><p>No live telemetry, disease diagnosis, independently validated operational forecasts or device actuation. Logs remain in this browser.</p><p>Sources: Digital Twin Platform Design chapters 3/5; 2024/2025 research; prototype.md; local CSV. No equipment, fish stocks or economic outcomes are invented.</p>`);$('.mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#exportBtn').onclick=()=>data&&exportData();window.addEventListener('hashchange',()=>{active=location.hash.slice(1)||'overview';$('.sidebar').classList.remove('open');window.scrollTo(0,0);if(data)render()});
$('#page').innerHTML='<div class="loading">Loading observation data…</div>';fetch('data.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(json=>{data=json;cursor=data.rows.length-1;active=location.hash.slice(1)||'overview';render()}).catch(e=>{$('#page').innerHTML=`<div class="card"><h2>Unable to load data</h2><p class="small-copy">Open the app through an HTTP server, not index.html directly.</p><p>${esc(e.message)}</p><button class="button" onclick="location.reload()">Retry</button></div>`});
